  reverb: { min: 0, max: 1, off: 0, def: [0, 0.8] }, // more send to the reverb
  pan: { min: -1, max: 1, off: 0, def: [-0.8, 0.8] },
  gate: { min: 0, max: 1, off: 0, def: [0, 1] }, // chops the sound in time: depth (rate: beats, 0.25)
